import os
from pathlib import Path

import pytest


def count_readable(names: list[str]) -> int:
    """Count the entries of `names` that are readable files inside `notes`.

    `notes` is a directory relative to the current working directory.
    Each name is resolved relative to `notes`, and subdirectory names such
    as "sub/b.txt" are valid. A name counts only if it refers to a regular
    file that can be opened and read, including an empty file. Missing
    files, directories, unreadable files and invalid names (for example
    ones containing a NUL byte) do not count. Any name that would reach a
    file outside `notes`, whether through "..", an absolute path, or a
    symlink pointing out of `notes`, does not count. Duplicate names are
    counted once per occurrence.
    """
    try:
        root = os.path.realpath("notes")
    except (OSError, ValueError):
        return 0
    prefix = root.rstrip(os.sep) + os.sep
    count = 0
    for name in names:
        if "\x00" in name or os.path.isabs(name):
            continue
        try:
            candidate = os.path.realpath(os.path.join(root, name))
            if not candidate.startswith(prefix):
                continue
            if not os.path.isfile(candidate):
                continue
            with open(candidate, "rb") as f:
                f.read(1)
        except (OSError, ValueError):
            continue
        count += 1
    return count


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello")
    (notes / "empty.txt").write_text("")
    (notes / "sub" / "b.txt").write_text("world")
    (tmp_path / "secret.txt").write_text("top secret")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_no_names(workdir: Path) -> None:
    assert count_readable([]) == 0


def test_simple_files(workdir: Path) -> None:
    assert count_readable(["a.txt"]) == 1
    assert count_readable(["a.txt", "empty.txt"]) == 2


def test_subdirectory_file(workdir: Path) -> None:
    assert count_readable(["sub/b.txt"]) == 1
    assert count_readable(["a.txt", "sub/b.txt"]) == 2


def test_empty_file_counts(workdir: Path) -> None:
    assert count_readable(["empty.txt"]) == 1


def test_missing_files(workdir: Path) -> None:
    assert count_readable(["nope.txt", "sub/nope.txt", "nodir/x.txt"]) == 0


def test_mixed_missing_and_present(workdir: Path) -> None:
    assert count_readable(["a.txt", "nope.txt", "sub/b.txt"]) == 2


def test_directories_do_not_count(workdir: Path) -> None:
    assert count_readable(["sub", "sub/", ".", "", "./"]) == 0


def test_duplicates_counted_per_entry(workdir: Path) -> None:
    assert count_readable(["a.txt", "a.txt", "sub/b.txt"]) == 3


def test_parent_traversal_rejected(workdir: Path) -> None:
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0
    assert count_readable(["../notes/../secret.txt"]) == 0
    assert count_readable(["a/../../secret.txt"]) == 0


def test_deep_traversal_rejected(workdir: Path) -> None:
    assert count_readable(["../../../../../../../../etc/passwd"]) == 0


def test_absolute_path_outside_rejected(workdir: Path) -> None:
    secret = str(workdir / "secret.txt")
    assert os.path.isabs(secret)
    assert count_readable([secret]) == 0
    assert count_readable(["/etc/passwd"]) == 0


def test_sibling_directory_with_notes_prefix_rejected(workdir: Path) -> None:
    sibling = workdir / "notes_evil"
    sibling.mkdir()
    (sibling / "x.txt").write_text("x")
    assert count_readable(["../notes_evil/x.txt"]) == 0


def test_symlink_to_outside_file_rejected(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert count_readable(["link.txt"]) == 0


def test_symlinked_directory_to_outside_rejected(workdir: Path) -> None:
    outside = workdir / "outside"
    outside.mkdir()
    (outside / "o.txt").write_text("o")
    link = workdir / "notes" / "dirlink"
    try:
        link.symlink_to(outside, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert count_readable(["dirlink/o.txt"]) == 0


def test_symlink_to_inside_file_allowed(workdir: Path) -> None:
    link = workdir / "notes" / "inner.txt"
    try:
        link.symlink_to(workdir / "notes" / "a.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert count_readable(["inner.txt"]) == 1


def test_invalid_names_do_not_raise(workdir: Path) -> None:
    assert count_readable(["a\x00.txt", "\x00", "a.txt\x00../secret.txt"]) == 0
    assert count_readable(["x" * 10000]) == 0


@pytest.mark.skipif(os.name == "nt", reason="POSIX permissions")
def test_unreadable_file_not_counted(workdir: Path) -> None:
    if hasattr(os, "geteuid") and os.geteuid() == 0:
        pytest.skip("root can read anything")
    locked = workdir / "notes" / "locked.txt"
    locked.write_text("x")
    locked.chmod(0)
    try:
        assert count_readable(["locked.txt", "a.txt"]) == 1
    finally:
        locked.chmod(0o600)


def test_missing_notes_directory(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "secret.txt").write_text("s")
    assert count_readable(["a.txt", "../secret.txt"]) == 0

